//! Raw AMF (Advanced Media Framework) declarations.
//!
//! `amf_api` is generated by bindgen from AMD's AMF SDK headers in C mode, where
//! every interface is a struct holding a pointer to its vtable (AMF SDK 1.4.33, MIT
//! licence: "Copyright (c) Advanced Micro Devices, Inc."). Its layout assertions are
//! compile-time, so a target whose ABI differs from the one the bindings were
//! generated on (Linux x86_64) fails to build. `wchar_t`, which differs between
//! Windows (16 bits) and Linux (32 bits), is defined here instead of being
//! generated; AMF property names are wide strings built with [`wide`] (bindgen
//! emits the headers' `L"..."` property names as narrow byte strings, which must
//! not be passed to AMF). The IIDs and the two exported entry points are written
//! out below.

#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    missing_docs,
    unnecessary_transmutes,
    unused_imports,
    clippy::all,
    clippy::undocumented_unsafe_blocks
)]

#[rustfmt::skip]
pub(crate) mod amf_api;

pub(crate) use amf_api::*;

/// The C `wchar_t` of the target.
#[cfg(target_os = "windows")]
pub(crate) type wchar_t = u16;
/// The C `wchar_t` of the target.
#[cfg(not(target_os = "windows"))]
pub(crate) type wchar_t = i32;

/// `AMF_FULL_VERSION` of the headers the bindings come from; the runtime must
/// report this version or a newer one.
pub(crate) const AMF_FULL_VERSION: u64 = ((AMF_VERSION_MAJOR as u64) << 48)
    | ((AMF_VERSION_MINOR as u64) << 32)
    | ((AMF_VERSION_RELEASE as u64) << 16)
    | AMF_VERSION_BUILD_NUM as u64;

pub(crate) type AMFInitFn = unsafe extern "C" fn(amf_uint64, *mut *mut AMFFactory) -> AMF_RESULT;
pub(crate) type AMFQueryVersionFn = unsafe extern "C" fn(*mut amf_uint64) -> AMF_RESULT;

const fn guid(d1: u32, d2: u16, d3: u16, d4: [u8; 8]) -> AMFGuid {
    AMFGuid {
        data1: d1,
        data2: d2,
        data3: d3,
        data41: d4[0],
        data42: d4[1],
        data43: d4[2],
        data44: d4[3],
        data45: d4[4],
        data46: d4[5],
        data47: d4[6],
        data48: d4[7],
    }
}

/// `IID_AMFBuffer` (core/Buffer.h).
pub(crate) const IID_AMF_BUFFER: AMFGuid = guid(
    0xb04b7248,
    0xb6f0,
    0x4321,
    [0xb6, 0x91, 0xba, 0xa4, 0x74, 0x0f, 0x9f, 0xcb],
);
/// `IID_AMFContext1` (core/Context.h).
pub(crate) const IID_AMF_CONTEXT1: AMFGuid = guid(
    0xd9e9f868,
    0x6220,
    0x44c6,
    [0xa2, 0x2f, 0x7c, 0xd6, 0xda, 0xc6, 0x86, 0x46],
);

/// A NUL-terminated wide string of `N - 1` ASCII characters, for AMF property names
/// and component ids (the headers' `L"..."` literals).
pub(crate) const fn wide<const N: usize>(s: &str) -> [wchar_t; N] {
    let bytes = s.as_bytes();
    assert!(bytes.len() + 1 == N, "wide string length");
    let mut out = [0 as wchar_t; N];
    let mut i = 0;
    while i < bytes.len() {
        assert!(bytes[i] < 0x80, "ASCII only");
        out[i] = bytes[i] as wchar_t;
        i += 1;
    }
    out
}

/// A `&'static [wchar_t]` wide string literal (NUL-terminated).
macro_rules! w {
    ($s:literal) => {{
        const W: [$crate::sys::wchar_t; $s.len() + 1] = $crate::sys::wide($s);
        &W
    }};
}
pub(crate) use w;

/// A wide, NUL-terminated name.
pub(crate) type Name = &'static [wchar_t];

/// Property names that differ between the H.264 and HEVC encoders.
#[derive(Debug)]
pub(crate) struct Names {
    pub component: Name,
    pub usage: Name,
    pub profile: Name,
    pub quality_preset: Name,
    pub frame_size: Name,
    pub frame_rate: Name,
    pub rate_control: Name,
    pub target_bitrate: Name,
    pub peak_bitrate: Name,
    pub vbv_size: Name,
    pub vbv_fullness: Name,
    pub qp_i: Name,
    pub qp_p: Name,
    pub extradata: Name,
    pub force_picture_type: Name,
    pub output_data_type: Name,
    pub output_color_profile: Name,
    pub output_transfer: Name,
    pub output_primaries: Name,
    pub bit_depth: Name,
    pub max_profile_cap: Name,
    pub throughput_cap: Name,
    pub enforce_hrd: Name,
    pub filler_data: Name,
}

